import argparse,json,urllib.request,time
from pathlib import Path
from playwright.sync_api import sync_playwright

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--url',default='http://127.0.0.1:8770');ap.add_argument('--out',required=True);ap.add_argument('--audio',required=True);ap.add_argument('--speech-text',required=True);args=ap.parse_args();out=Path(args.out).resolve();out.mkdir(parents=True,exist_ok=True);errors=[];checks=[]
 boot=json.load(urllib.request.urlopen(args.url+'/api/bootstrap'));token=boot['token']
 def api(path,data=None):
  r=urllib.request.Request(args.url+path,data=json.dumps(data,ensure_ascii=False).encode() if data is not None else None,headers={'Content-Type':'application/json','X-Studio-Token':token});return json.load(urllib.request.urlopen(r,timeout=30))
 with sync_playwright() as pw:
  b=pw.chromium.launch(channel='msedge',headless=False,args=['--use-fake-device-for-media-stream','--use-file-for-fake-audio-capture='+str(Path(args.audio).resolve())]);ctx=b.new_context(permissions=['microphone'],viewport={'width':1440,'height':1080},reduced_motion='reduce');page=ctx.new_page();page.on('pageerror',lambda e:errors.append(e.stack or str(e)));page.goto(args.url);page.wait_for_selector('.entry-card');assert page.locator('.entry-card').count()==4;page.screenshot(path=str(out/'dashboard.png'));checks.append('dashboard four prominent entry cards')
  page.click('[data-v2="blank"]');page.wait_for_selector('#page-text');assert page.input_value('#page-text')=='';pid=page.evaluate('P.id');checks.append('new project has editable blank page')
  page.locator('[data-tl="collapse"]').click()
  page.fill('#page-title','连接与录制');page.fill('#page-text','先把设备连接好。然后打开工作台，开始录制。');page.locator('#page-notes').click();page.wait_for_timeout(900)
  page.evaluate('window.editorNode=document.querySelector("#page-text")');page.locator('.annotations summary').click();page.click('[data-tag="flow"]');assert page.evaluate('window.editorNode===document.querySelector("#page-text")');assert page.locator('.annotation').count()==1;page.wait_for_timeout(900);tagid=page.evaluate('P.pages[0].tags[0].id');checks.append('tag add preserves editor DOM and timeline event')
  page.locator('[data-tag-label]').fill('连接步骤动画');page.locator('#page-notes').click();page.wait_for_timeout(900);assert '连接步骤动画' in page.locator('[data-clip="tag_'+tagid+'"]').inner_text();checks.append('page label synchronizes timeline')
  page.locator('[data-clip="tag_'+tagid+'"]').dblclick();page.fill('#clip-name','设备连接演示');page.fill('#clip-duration','2');page.click('#clip-save');assert page.input_value('[data-tag-label]')=='设备连接演示';checks.append('timeline inspector synchronizes page label')
  page.locator('[data-tl="add"]').click();page.fill('#new-clip-name','额外演示');page.fill('#new-clip-duration','10');page.select_option('#new-clip-page','');before=page.evaluate('P.timeline.duration');page.click('#new-clip-create');assert abs(page.evaluate('P.timeline.duration')-before-10)<.01;checks.append('main insert increases duration by ten seconds')
  clip=page.locator('[data-clip="tag_'+tagid+'"]');box=clip.bounding_box();old=page.evaluate('P.timeline.clips.find(c=>c.tag_id).start');page.mouse.move(box['x']+box['width']/2,box['y']+16);page.mouse.down();page.mouse.move(box['x']+box['width']/2+30,box['y']+16,steps=8);page.mouse.up();page.wait_for_timeout(1000);assert page.evaluate('P.timeline.clips.find(c=>c.tag_id).start')>old;checks.append('real pointer drag commits new timing')
  current=api('/api/project?id='+pid);page.reload();page.wait_for_selector('#page-text');assert len(api('/api/project?id='+pid)['timeline']['clips'])==len(current['timeline']['clips']);checks.append('project and timeline persist across reload')
  page.click('[data-cmd="rewrite"]');page.wait_for_selector('.vditor-ir');page.wait_for_function('mdEditor && mdEditor.getValue().length>0');assert page.locator('.vditor-toolbar svg').count()>15;page.click('#draft-rewrite');page.wait_for_function('manuscript.status==="pending_host"');did=page.evaluate('manuscript.id');original=api('/api/v2/draft?id='+did)['text'];api('/api/v2/complete',{'id':did,'result':'先把设备连接好。接着打开工作台，就可以开始录制了。'});page.wait_for_selector('#draft-adopt');assert api('/api/v2/draft?id='+did)['text']==original;page.click('#draft-adopt');page.wait_for_function('mdEditor.getValue().includes("就可以开始录制")');checks.append('Markdown SVG toolbar and host AI review/adoption round trip')
  page.click('#draft-paginate');page.wait_for_function('manuscript.status==="pending_host"');did=page.evaluate('manuscript.id');api('/api/v2/complete',{'id':did,'result':{'pages':[{'title':'连接并开始录制','sentences':[0,1],'reason':'同一操作主题，整句保留'}]}});page.wait_for_selector('.pagination-preview article');page.once('dialog',lambda dialog:dialog.accept());page.click('#draft-create');page.wait_for_function('!document.querySelector("#dialog").open');page.wait_for_function('document.querySelector("#page-text")?.value.includes("就可以开始录制")');assert '就可以开始录制' in page.input_value('#page-text');checks.append('semantic AI page boundary proposal applied to project')
  page.locator('.project-menu summary').click();page.locator('.project-menu [data-v2="drafts"]').click();page.click('[data-draft="'+did+'"]');page.wait_for_selector('.vditor-ir');page.check('#draft-append');page.click('#draft-create');page.wait_for_function('!document.querySelector("#dialog").open && P.pages.length===2');page.fill('#page-title','追加后仍可编辑');page.locator('#page-notes').click();page.wait_for_timeout(1000);page.reload();page.wait_for_selector('#page-text');assert len(set(pg['id'] for pg in api('/api/project?id='+pid)['pages']))==2;assert page.input_value('#page-title')=='追加后仍可编辑';checks.append('A4: reusing AI draft through append UI creates unique editable pages')
  page.locator('[data-tl="collapse"]').click()
  page.locator('[data-track="main"] [data-clip]').first.dblclick();page.wait_for_selector('#clip-save');assert page.locator('#clip-enabled').count()==0;assert '不支持禁用' in page.locator('#dialog-body').inner_text();page.click('#clip-save');checks.append('A7: main inspector offers trim/delete and no misleading enable switch')
  page.locator('.annotations summary').click();page.click('[data-tag="title"]');page.wait_for_timeout(900);page.screenshot(path=str(out/'timeline.png'),full_page=True)
  # Real audio traverses AudioWorklet, HTTP chunks, local recognizer, and prompter text matching.
  page.fill('#page-text',Path(args.speech_text).read_text(encoding='utf-8'));page.locator('#page-notes').click();page.wait_for_timeout(1100)
  with page.expect_popup() as pop:page.click('[data-workflow="prompt"]')
  prompt=pop.value;prompt.on('pageerror',lambda e:errors.append(e.stack or str(e)));prompt.wait_for_selector('#prompt-timeline-toggle');prompt.locator('#prompt-timeline-toggle').click();prompt.wait_for_selector('#prompt-tracks');assert prompt.locator('.prompt-track').count()==4;prompt.click('#voice');prompt.wait_for_function('typeof promptMic!=="undefined" && promptMic.active',timeout=20000);prompt.wait_for_function('position>5',timeout=20000);assert prompt.locator('.said').count()>5;prompt.screenshot(path=str(out/'prompter.png'));checks.append('audio stream through local ASR advances highlighting and timeline needle')
  prompt.click('#voice');prompt.wait_for_function('!promptMic.active && !promptMic.stream');prompt.click('#retake');assert prompt.evaluate('position')==0;checks.append('stop releases stream; retake resets position');prompt.close()
  page.click('[data-stage="2"]');page.wait_for_selector('[data-workflow="recording"]');page.click('[data-stage="3"]');page.wait_for_selector('.tabs');page.click('[data-tab="assets"]');checks.append('empty video stage offers import and finish still exposes assets')
  page.click('[data-v2="home"]');page.wait_for_selector('.entry-card');page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(300);assert not page.evaluate('document.documentElement.scrollWidth>innerWidth+1');checks.append('mobile dashboard no horizontal overflow');b.close()
 assert not errors,errors
 (out/'results.json').write_text(json.dumps({'status':'PASS','checks':checks,'errors':errors,'speech_input':'recorded Chinese audio via browser fake capture; physical microphone tested separately'},ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'status':'PASS','checks':len(checks)}))
if __name__=='__main__':main()
